package project.init.account.domain.entity;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.Id;import jakarta.persistence.PrePersist;import jakarta.persistence.PreUpdate;import jakarta.persistence.Table;import lombok.Getter;import lombok.Setter;import project.init.framework.utils.DateTimeUtils;import java.time.Instant;@Entity@Getter@Setter@Table(name = "account_info")public class AccountInfo {    @Id    @Column(name = "account_code", length = 50, nullable = false)    private String accountCode;    @Column(name = "account_name", length = 100)    private String accountName;    @Column(name = "account_email", length = 100, nullable = false, unique = true)    private String accountEmail;    @Column(name = "account_mobile", length = 20)    private String accountMobile;    @Column(name = "account_address", columnDefinition = "TEXT")    private String accountAddress;    @Column(name = "created_at", updatable = false)    private Instant createdAt;    @Column(name = "updated_at")    private Instant updatedAt;    @PrePersist    protected void onCreate() {        createdAt = DateTimeUtils.getCurrentTimeUTC();        updatedAt = DateTimeUtils.getCurrentTimeUTC();    }    @PreUpdate    protected void onUpdate() {        updatedAt = DateTimeUtils.getCurrentTimeUTC();    }}